[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --navy: #1B1464;
      --navy-dark: #130f4a;
      --yellow: #FFD930;
      --yellow-hover: #f5cc1a;
      --blue: #0066FF;
      --blue-light: #e8f0ff;
      --teal: #00C6A2;
      --teal-light: #e0faf5;
      --white: #ffffff;
      --gray-50: #f8f9fc;
      --gray-100: #f1f3f8;
      --gray-200: #e4e7ef;
      --gray-400: #9aa3b8;
      --gray-600: #5a6382;
      --gray-800: #2d3452;
      --shadow-sm: 0 1px 3px rgba(27,20,100,0.08);
      --shadow-md: 0 4px 16px rgba(27,20,100,0.12);
      --shadow-lg: 0 12px 40px rgba(27,20,100,0.16);
      --shadow-xl: 0 24px 64px rgba(27,20,100,0.2);
      --radius: 12px;
      --radius-lg: 20px;
      --radius-xl: 28px;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      font-size: 16px;
      line-height: 1.6;
      color: var(--gray-800);
      background: var(--white);
      overflow-x: hidden;
    }

    a { text-decoration: none; color: inherit; }
    img { max-width: 100%; display: block; }

    /* ── HEADER ── */
    .header {
      position: fixed;
      top: 0; left: 0; right: 0;
      z-index: 1000;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--gray-200);
      transition: box-shadow 0.2s;
    }
    .header.scrolled { box-shadow: var(--shadow-md); }

    .header-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .logo {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 22px;
      font-weight: 800;
      color: var(--navy);
      letter-spacing: -0.5px;
    }
    .logo-mark {
      width: 36px; height: 36px;
      background: var(--navy);
      border-radius: 10px;
      display: flex; align-items: center; justify-content: center;
      flex-shrink: 0;
    }
    .logo-mark svg { width: 20px; height: 20px; }
    .logo span { color: var(--yellow); }

    .nav-links {
      display: flex;
      align-items: center;
      gap: 8px;
      list-style: none;
    }
    .nav-links a {
      padding: 8px 14px;
      border-radius: 8px;
      font-size: 15px;
      font-weight: 500;
      color: var(--gray-600);
      transition: color 0.15s, background 0.15s;
    }
    .nav-links a:hover { color: var(--navy); background: var(--gray-100); }
    .nav-links .btn-login {
      color: var(--navy);
      font-weight: 600;
    }
    .nav-links .btn-signup {
      background: var(--navy);
      color: var(--white);
      padding: 9px 20px;
      border-radius: 8px;
      font-weight: 600;
      transition: background 0.15s, transform 0.1s;
    }
    .nav-links .btn-signup:hover { background: var(--navy-dark); color: var(--white); transform: translateY(-1px); }

    .hamburger {
      display: none;
      flex-direction: column;
      gap: 5px;
      cursor: pointer;
      padding: 8px;
      border-radius: 8px;
      transition: background 0.15s;
      background: none;
      border: none;
    }
    .hamburger:hover { background: var(--gray-100); }
    .hamburger span {
      display: block;
      width: 22px; height: 2px;
      background: var(--navy);
      border-radius: 2px;
      transition: transform 0.25s, opacity 0.25s;
    }
    .hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
    .hamburger.open span:nth-child(2) { opacity: 0; }
    .hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

    /* Mobile nav drawer */
    .mobile-nav {
      display: none;
      position: fixed;
      top: 72px; left: 0; right: 0; bottom: 0;
      background: var(--white);
      z-index: 999;
      padding: 24px;
      transform: translateX(100%);
      transition: transform 0.3s cubic-bezier(0.4,0,0.2,1);
      border-top: 1px solid var(--gray-200);
      overflow-y: auto;
    }
    .mobile-nav.open {
      transform: translateX(0);
    }
    .mobile-nav a {
      display: block;
      padding: 16px 0;
      font-size: 18px;
      font-weight: 600;
      color: var(--gray-800);
      border-bottom: 1px solid var(--gray-100);
      transition: color 0.15s;
    }
    .mobile-nav a:hover { color: var(--navy); }
    .mobile-nav .mobile-signup {
      display: inline-block;
      margin-top: 24px;
      background: var(--navy);
      color: var(--white) !important;
      padding: 14px 32px;
      border-radius: 10px;
      border-bottom: none;
      font-size: 16px;
    }

    /* ── HERO ── */
    .hero {
      padding-top: 72px;
      background: linear-gradient(160deg, var(--navy) 0%, #2d2890 55%, #3d48c8 100%);
      position: relative;
      overflow: hidden;
      min-height: 580px;
      display: flex;
      align-items: center;
    }

    .hero-bg-shapes {
      position: absolute;
      inset: 0;
      pointer-events: none;
      overflow: hidden;
    }
    .hero-bg-shapes::before {
      content: '';
      position: absolute;
      top: -120px; right: -80px;
      width: 600px; height: 600px;
      background: radial-gradient(circle, rgba(255,217,48,0.12) 0%, transparent 65%);
      border-radius: 50%;
    }
    .hero-bg-shapes::after {
      content: '';
      position: absolute;
      bottom: -100px; left: -60px;
      width: 400px; height: 400px;
      background: radial-gradient(circle, rgba(0,198,162,0.15) 0%, transparent 65%);
      border-radius: 50%;
    }

    .hero-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 80px 24px 100px;
      position: relative;
      z-index: 1;
      width: 100%;
    }

    .hero-eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(255,255,255,0.12);
      border: 1px solid rgba(255,255,255,0.2);
      color: var(--yellow);
      font-size: 13px;
      font-weight: 600;
      letter-spacing: 0.5px;
      text-transform: uppercase;
      padding: 6px 14px;
      border-radius: 100px;
      margin-bottom: 24px;
    }
    .hero-eyebrow svg { width: 14px; height: 14px; }

    .hero-title {
      font-size: clamp(36px, 5.5vw, 64px);
      font-weight: 900;
      line-height: 1.08;
      letter-spacing: -2px;
      color: var(--white);
      max-width: 780px;
      margin-bottom: 20px;
    }
    .hero-title em {
      font-style: normal;
      color: var(--yellow);
    }

    .hero-subtitle {
      font-size: clamp(16px, 1.8vw, 20px);
      color: rgba(255,255,255,0.78);
      max-width: 580px;
      margin-bottom: 48px;
      line-height: 1.6;
    }

    /* ── SEARCH CARD ── */
    .search-card {
      background: var(--white);
      border-radius: var(--radius-xl);
      padding: 28px 28px 28px;
      box-shadow: var(--shadow-xl);
      max-width: 900px;
    }

    .search-form {
      display: grid;
      grid-template-columns: 1fr 1fr 1fr auto;
      gap: 12px;
      align-items: end;
    }

    .search-field {
      display: flex;
      flex-direction: column;
      gap: 6px;
      position: relative;
    }

    .search-field label {
      font-size: 12px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.6px;
      color: var(--gray-600);
    }

    .search-field input,
    .search-field select {
      width: 100%;
      padding: 12px 16px;
      border: 2px solid var(--gray-200);
      border-radius: 10px;
      font-size: 15px;
      font-family: inherit;
      color: var(--gray-800);
      background: var(--gray-50);
      transition: border-color 0.15s, background 0.15s, box-shadow 0.15s;
      outline: none;
      appearance: none;
    }
    .search-field input:focus,
    .search-field select:focus {
      border-color: var(--blue);
      background: var(--white);
      box-shadow: 0 0 0 4px rgba(0,102,255,0.1);
    }
    .search-field input::placeholder { color: var(--gray-400); }

    .search-field .field-icon {
      position: absolute;
      right: 14px;
      bottom: 14px;
      color: var(--gray-400);
      pointer-events: none;
    }
    .search-field .field-icon svg { width: 16px; height: 16px; }

    .search-field select {
      padding-right: 40px;
      cursor: pointer;
      color: var(--gray-400);
    }
    .search-field select.has-value { color: var(--gray-800); }

    /* Autocomplete dropdown */
    .autocomplete-dropdown {
      position: absolute;
      top: calc(100% + 6px);
      left: 0; right: 0;
      background: var(--white);
      border: 2px solid var(--blue);
      border-radius: 12px;
      box-shadow: var(--shadow-lg);
      z-index: 100;
      overflow: hidden;
      display: none;
    }
    .autocomplete-dropdown.visible { display: block; }
    .autocomplete-item {
      display: flex;
      align-items: center;
      gap: 12px;
      padding: 12px 16px;
      cursor: pointer;
      transition: background 0.1s;
      font-size: 14px;
    }
    .autocomplete-item:hover,
    .autocomplete-item.focused { background: var(--blue-light); }
    .autocomplete-item svg { width: 16px; height: 16px; color: var(--blue); flex-shrink: 0; }
    .autocomplete-item .item-label { font-weight: 600; color: var(--gray-800); }
    .autocomplete-item .item-type { font-size: 12px; color: var(--gray-400); margin-left: auto; }

    .btn-search {
      background: var(--yellow);
      color: var(--navy);
      border: none;
      padding: 14px 28px;
      border-radius: 10px;
      font-size: 16px;
      font-weight: 700;
      font-family: inherit;
      cursor: pointer;
      display: flex;
      align-items: center;
      gap: 8px;
      transition: background 0.15s, transform 0.1s, box-shadow 0.15s;
      white-space: nowrap;
      height: 48px;
    }
    .btn-search:hover {
      background: var(--yellow-hover);
      transform: translateY(-1px);
      box-shadow: 0 6px 20px rgba(255,217,48,0.5);
    }
    .btn-search svg { width: 18px; height: 18px; }

    .hero-trust {
      display: flex;
      align-items: center;
      gap: 20px;
      margin-top: 20px;
      flex-wrap: wrap;
    }
    .trust-item {
      display: flex;
      align-items: center;
      gap: 6px;
      font-size: 13px;
      color: var(--gray-600);
    }
    .trust-item svg { width: 15px; height: 15px; color: var(--teal); }

    /* ── STATS BAR ── */
    .stats-bar {
      background: var(--navy);
      padding: 0;
    }

    .stats-inner {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 24px;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
    }

    .stat-item {
      padding: 32px 24px;
      display: flex;
      flex-direction: column;
      align-items: center;
      text-align: center;
      position: relative;
    }
    .stat-item + .stat-item::before {
      content: '';
      position: absolute;
      left: 0; top: 25%; bottom: 25%;
      width: 1px;
      background: rgba(255,255,255,0.12);
    }

    .stat-value {
      font-size: clamp(28px, 3.5vw, 40px);
      font-weight: 900;
      letter-spacing: -1px;
      color: var(--yellow);
      line-height: 1;
      margin-bottom: 6px;
    }
    .stat-label {
      font-size: 14px;
      color: rgba(255,255,255,0.65);
      font-weight: 500;
    }

    /* ── SECTION SHARED ── */
    .section {
      padding: 96px 24px;
    }
    .section-inner {
      max-width: 1200px;
      margin: 0 auto;
    }
    .section-eyebrow {
      font-size: 13px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--teal);
      margin-bottom: 12px;
    }
    .section-title {
      font-size: clamp(28px, 3.5vw, 44px);
      font-weight: 800;
      letter-spacing: -1px;
      color: var(--navy);
      line-height: 1.15;
      margin-bottom: 16px;
    }
    .section-subtitle {
      font-size: 18px;
      color: var(--gray-600);
      max-width: 560px;
      line-height: 1.6;
    }
    .section-header {
      margin-bottom: 56px;
    }

    /* ── SPECIALTIES ── */
    .specialties-section { background: var(--gray-50); }

    .specialties-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
      gap: 16px;
    }

    .specialty-card {
      background: var(--white);
      border: 2px solid var(--gray-200);
      border-radius: var(--radius-lg);
      padding: 28px 20px;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 14px;
      cursor: pointer;
      transition: border-color 0.2s, box-shadow 0.2s, transform 0.2s;
      text-align: center;
    }
    .specialty-card:hover {
      border-color: var(--blue);
      box-shadow: var(--shadow-md);
      transform: translateY(-4px);
    }

    .specialty-icon {
      width: 60px; height: 60px;
      border-radius: 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 28px;
      flex-shrink: 0;
    }

    .specialty-name {
      font-size: 15px;
      font-weight: 700;
      color: var(--navy);
      line-height: 1.3;
    }
    .specialty-desc {
      font-size: 13px;
      color: var(--gray-400);
      line-height: 1.4;
    }

    .specialty-card:hover .specialty-name { color: var(--blue); }

    /* ── HOW IT WORKS ── */
    .how-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }

    .steps-list {
      display: flex;
      flex-direction: column;
      gap: 36px;
    }
    .step {
      display: flex;
      gap: 20px;
    }
    .step-number {
      width: 48px; height: 48px;
      border-radius: 14px;
      background: var(--navy);
      color: var(--yellow);
      font-size: 20px;
      font-weight: 900;
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }
    .step-content {}
    .step-title {
      font-size: 18px;
      font-weight: 700;
      color: var(--navy);
      margin-bottom: 8px;
    }
    .step-desc {
      font-size: 15px;
      color: var(--gray-600);
      line-height: 1.6;
    }

    .how-illustration {
      background: linear-gradient(145deg, var(--blue-light) 0%, var(--teal-light) 100%);
      border-radius: var(--radius-xl);
      padding: 48px 40px;
      display: flex;
      flex-direction: column;
      gap: 16px;
    }

    /* Faux app card */
    .app-card {
      background: var(--white);
      border-radius: var(--radius);
      padding: 16px 20px;
      box-shadow: var(--shadow-sm);
    }
    .app-card-header {
      display: flex;
      align-items: center;
      gap: 12px;
      margin-bottom: 12px;
    }
    .avatar {
      width: 44px; height: 44px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--blue) 0%, var(--teal) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      color: white;
      font-weight: 700;
      font-size: 15px;
      flex-shrink: 0;
    }
    .app-card-name { font-size: 15px; font-weight: 700; color: var(--navy); }
    .app-card-specialty { font-size: 13px; color: var(--gray-400); }
    .app-card-stars { color: #FFAA00; font-size: 13px; letter-spacing: 1px; }
    .app-card-stars span { color: var(--gray-400); font-size: 12px; margin-left: 4px; }

    .slot-row {
      display: flex;
      gap: 8px;
      flex-wrap: wrap;
    }
    .slot {
      padding: 6px 12px;
      border-radius: 8px;
      font-size: 13px;
      font-weight: 600;
      background: var(--blue-light);
      color: var(--blue);
      cursor: pointer;
      transition: background 0.15s, color 0.15s;
    }
    .slot.available-today {
      background: var(--teal-light);
      color: var(--teal);
    }
    .slot.selected {
      background: var(--blue);
      color: var(--white);
    }

    .confirm-btn {
      width: 100%;
      padding: 12px;
      background: var(--teal);
      color: white;
      border: none;
      border-radius: 10px;
      font-size: 14px;
      font-weight: 700;
      font-family: inherit;
      cursor: pointer;
      transition: background 0.15s;
      margin-top: 8px;
    }
    .confirm-btn:hover { background: #00b394; }

    /* ── TESTIMONIALS ── */
    .testimonials-section { background: var(--navy); }
    .testimonials-section .section-eyebrow { color: var(--yellow); }
    .testimonials-section .section-title { color: var(--white); }

    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .testimonial-card {
      background: rgba(255,255,255,0.06);
      border: 1px solid rgba(255,255,255,0.1);
      border-radius: var(--radius-lg);
      padding: 32px 28px;
      transition: background 0.2s, transform 0.2s;
    }
    .testimonial-card:hover {
      background: rgba(255,255,255,0.1);
      transform: translateY(-3px);
    }
    .testimonial-stars { color: var(--yellow); font-size: 16px; margin-bottom: 16px; letter-spacing: 2px; }
    .testimonial-quote {
      font-size: 16px;
      color: rgba(255,255,255,0.88);
      line-height: 1.7;
      margin-bottom: 24px;
      font-style: italic;
    }
    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .author-avatar {
      width: 42px; height: 42px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-weight: 700;
      font-size: 16px;
      color: var(--navy);
      flex-shrink: 0;
    }
    .author-name { font-size: 15px; font-weight: 700; color: var(--white); }
    .author-location { font-size: 13px; color: rgba(255,255,255,0.5); }

    /* ── APP PROMO ── */
    .app-promo {
      background: linear-gradient(135deg, var(--gray-50) 0%, var(--blue-light) 100%);
    }
    .app-promo-inner {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }
    .app-features-list {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 16px;
      margin: 32px 0;
    }
    .app-feature {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      font-size: 16px;
      color: var(--gray-800);
    }
    .app-feature svg {
      width: 20px; height: 20px;
      color: var(--teal);
      flex-shrink: 0;
      margin-top: 2px;
    }

    .store-buttons {
      display: flex;
      gap: 12px;
      flex-wrap: wrap;
    }
    .store-btn {
      display: flex;
      align-items: center;
      gap: 10px;
      background: var(--navy);
      color: var(--white);
      padding: 12px 20px;
      border-radius: 12px;
      font-size: 14px;
      font-weight: 600;
      transition: background 0.15s, transform 0.1s;
    }
    .store-btn:hover { background: var(--navy-dark); transform: translateY(-2px); }
    .store-btn svg { width: 22px; height: 22px; flex-shrink: 0; }
    .store-btn-sub { font-size: 11px; font-weight: 400; opacity: 0.7; display: block; }

    .app-mockup {
      background: var(--navy);
      border-radius: 32px;
      padding: 32px 24px;
      max-width: 320px;
      margin: 0 auto;
      box-shadow: var(--shadow-xl);
      position: relative;
    }
    .app-mockup::before {
      content: '';
      position: absolute;
      top: 16px; left: 50%;
      transform: translateX(-50%);
      width: 80px; height: 5px;
      background: rgba(255,255,255,0.2);
      border-radius: 4px;
    }
    .mockup-screen {
      background: var(--white);
      border-radius: 20px;
      padding: 20px 16px;
      margin-top: 24px;
    }
    .mockup-greeting {
      font-size: 13px;
      color: var(--gray-400);
      margin-bottom: 4px;
    }
    .mockup-name {
      font-size: 17px;
      font-weight: 800;
      color: var(--navy);
      margin-bottom: 16px;
    }
    .mockup-upcoming {
      background: var(--navy);
      border-radius: 14px;
      padding: 14px 16px;
      color: white;
      margin-bottom: 16px;
    }
    .mockup-upcoming-label {
      font-size: 11px;
      text-transform: uppercase;
      letter-spacing: 0.8px;
      opacity: 0.6;
      margin-bottom: 6px;
    }
    .mockup-upcoming-doc {
      font-size: 15px;
      font-weight: 700;
      margin-bottom: 2px;
    }
    .mockup-upcoming-time {
      font-size: 13px;
      opacity: 0.75;
    }
